// Meter An uncalibrated meter reading. Neither target rig reports dBm: Kenwood
// SM returns 0..30 meter dots, Icom 15 02 returns 0..255. `s` is present
// only where a per-model calibration table exists.
type Meter struct {
	Raw   int                        `json:"raw"`
	S     nullable.Nullable[float64] `json:"s,omitempty"`
	Scale int                        `json:"scale"`
}

// Mode UNKNOWN is reported for a radio that has not connected yet, or whose rig
// answered with a value it documents as a setting failure (Kenwood MD0/MD8).
// It is never accepted as input.
//
// Not every radio has every mode: DV and DD are D-STAR modes on Icom's
// VHF/UHF and microwave sets, ATV is IC-905 only, and PSK is absent from
// those same radios. C4FM is Yaesu's, and comes in three spellings because
// the radios do: an FT-991A's mode table says only `C4FM`, while an FTX-1
// selects `C4FM-DN` and `C4FM-VW` separately. A radio's `caps.modes` lists
// what it will actually accept, and a mode outside that list is rejected
// with 422.
//
// `WFM` and `DIG` belong to the FT-857/FT-897 generation. `DIG` is one
// mode for the same reason `C4FM` is: which digital mode it actually is —
// RTTY, PSK31 or a USER slot, and on which sideband — is a menu item no
// CAT command reads.
//
// `WFM` is the one value that can appear in `state.mode` and never in
// `caps.modes`: those radios report wide FM in their status answer and
// have no command to select it, so it is readable and not settable. A
// client should render a mode it reads rather than assume it came from the
// capability list.
type Mode string

// NotchWidth How wide the manual notch bites. Icom only; `caps.notch_widths` is empty
// elsewhere, because a Kenwood accepts a width and then always answers 0
// for it, and remoses does not offer one it could write and never read
// back.
type NotchWidth string

// Power Transmit power in every form the backend can supply. The target rigs
// disagree about units and normalising that away would lose information:
// Kenwood PC is watts, Icom 14 0A is a relative index.
type Power struct {
	// Native The value as it appears on the wire.
	Native int `json:"native"`

	// Pct Normalised 0..100 against the rig's maximum for the current mode.
	Pct float64 `json:"pct"`

	// Watts Absolute watts, null when the rig has no watt-accurate scale.
	Watts nullable.Nullable[float64] `json:"watts,omitempty"`
}

// PowerSet Exactly one of watts or pct.
type PowerSet struct {
	Pct   *float64 `json:"pct,omitempty"`
	Watts *float64 `json:"watts,omitempty"`
}

// PowerSwitch Switch the radio itself off or on.
//
// `off` is the recoverable off: on a radio with a choice it is the one
// that draws more standby current and wakes on a single command.
// `off_deep` asks for the lowest standby current the radio offers — on a
// Kenwood, the same as its front-panel switch — which needs the longer
// wake sequence afterwards. A radio with only one off sends it either way.
type PowerSwitch string

// Problem RFC 9457 problem detail, with a radio_id extension member.
type Problem struct {
	Character *string    `json:"character,omitempty"`
	Charset   *string    `json:"charset,omitempty"`
	Detail    *string    `json:"detail,omitempty"`
	ExpiresAt *time.Time `json:"expires_at,omitempty"`
	Instance  *string    `json:"instance,omitempty"`
	LockedBy  *string    `json:"locked_by,omitempty"`
	Offset    *int       `json:"offset,omitempty"`
	RadioID   *string    `json:"radio_id,omitempty"`
	Status    int        `json:"status"`
	Title     string     `json:"title"`
	Type      *string    `json:"type,omitempty"`
}

// Radio defines model for Radio.
type Radio struct {
	// Backend The protocol family remoses speaks to this radio.
	//
	// `yaesu` covers both of Yaesu's CAT systems: the ASCII dialect the modern
	// radios speak and the five-byte binary one of the FT-857/FT-897
	// generation. The model chooses, so there is one backend name.
	Backend Backend `json:"backend"`

	// Caps What this radio can do, as far as remoses can work it. Read these rather
	// than guessing from the model name — and rather than inferring a
	// capability from a state field, since most of those are absent both when
	// the radio has no such control and when it is simply switched off.
	//
	// Everything the daemon can answer for every radio is required, so a
	// client need not treat "the flag is missing" as a third case. The
	// optional ones are the lists and figures that only some radios have at
	// all: an attenuator's steps, the AGC speeds, a watt figure.
	Caps      Caps      `json:"caps"`
	Connected bool      `json:"connected"`
	ID        string    `json:"id"`
	Limits    Limits    `json:"limits"`
	Lock      LockState `json:"lock"`
	Name      string    `json:"name"`
}

